// OPI project page.
// Method schematics are illustrative (tagged "Schematic"); every result number comes from
// data/results.js, generated by tools/build_results.py from the paper's LaTeX tables.

(function () {
  const R = window.OPI_RESULTS;
  const C = {
    ink: "#20211f",
    ink2: "#343630",
    muted: "#646860",
    faint: "#898781",
    line: "#e4e3dc",
    lineStrong: "#c9ccc3",
    wash: "#f4f4ef",
    grid: "#ecebe5",
    good: "#0b7a0b",
    bad: "#b8322f",
    base: "#b4b2aa",
    ours: Viz.css("--ours") || "#4e79a7",
    learner: Viz.css("--learner") || "#4e79a7",
    oracle1: Viz.css("--oracle1") || "#f28e2b",
    oracle2: Viz.css("--oracle2") || "#59a14f",
    oracle3: Viz.css("--oracle3") || "#b07aa1",
    bp: Viz.css("--bp") || "#1c5cab",
    pi: Viz.css("--pi") || "#6a4ca8",
  };
  const ACTOR = [C.learner, C.oracle1, C.oracle2];
  const byId = (id) => document.getElementById(id);

  function node(tag, className, html) {
    const n = document.createElement(tag);
    if (className) n.className = className;
    if (html !== undefined) n.innerHTML = html;
    return n;
  }

  // ---------- TeX labels over SVG (same mechanism as the ProAct page) ----------
  function typeset(el) {
    const go = () => window.MathJax.typesetPromise([el]).catch(() => {});
    if (window.MathJax?.startup?.promise) window.MathJax.startup.promise.then(go);
    else window.addEventListener("load", () => window.MathJax?.startup?.promise?.then(go), { once: true });
  }

  function svgStage(host, width, height, label) {
    const stage = node("div", "svg-stage");
    stage.style.width = `${width}px`;
    stage.style.height = `${height}px`;
    host.appendChild(stage);
    const svg = Viz.svgRoot(stage, width, height, label);
    const layer = node("div", "math-layer");
    stage.appendChild(layer);
    const tex = (x, y, html, { cls = "", align = "center", color } = {}) => {
      const d = node("div", `mlabel ${align} ${cls}`.trim(), html);
      d.style.left = `${x}px`;
      d.style.top = `${y}px`;
      if (color) d.style.color = color;
      layer.appendChild(d);
      return d;
    };
    return { svg, tex, done: () => typeset(layer) };
  }

  // polyline with an arrowhead at its last point
  function arrow(svg, pts, color = "#9a9992", { dash, width = 1.8 } = {}) {
    const d = pts.map((p, i) => `${i ? "L" : "M"}${p[0]},${p[1]}`).join(" ");
    Viz.el("path", { d, fill: "none", stroke: color, "stroke-width": width, "stroke-dasharray": dash || null, "stroke-linejoin": "round" }, svg);
    const [x0, y0] = pts[pts.length - 2];
    const [x, y] = pts[pts.length - 1];
    const ang = Math.atan2(y - y0, x - x0);
    const s = 7 + width;
    const p1 = [x - s * Math.cos(ang - 0.42), y - s * Math.sin(ang - 0.42)];
    const p2 = [x - s * Math.cos(ang + 0.42), y - s * Math.sin(ang + 0.42)];
    Viz.el("path", { d: `M${p1[0]},${p1[1]} L${x},${y} L${p2[0]},${p2[1]}`, fill: "none", stroke: color, "stroke-width": width, "stroke-linejoin": "round" }, svg);
  }

  function segmented(seg, onPick) {
    seg.querySelectorAll("button").forEach((b) =>
      b.addEventListener("click", () => {
        seg.querySelectorAll("button").forEach((x) => x.setAttribute("aria-pressed", String(x === b)));
        onPick(b);
      })
    );
  }

  // ======================================================================
  // Overview: pipeline
  // ======================================================================
  function renderPipeline(card = byId("pipeline")) {
    const host = node("div");
    const legend = node("div", "toy-legend pipe-legend");
    legend.innerHTML = [
      [C.learner, String.raw`learner \(\pi_0=\pi_\theta\)`],
      [C.oracle1, String.raw`highway expert \(\pi_1\)`],
      [C.oracle2, String.raw`city expert \(\pi_2\)`],
      [C.oracle3, String.raw`rural expert \(\pi_3\)`],
    ].map(([c, t]) => `<span class="tl-item"><i class="tl-dot" style="background:${c}"></i>${t}</span>`).join("");
    card.replaceChildren(host, legend);
    typeset(legend);
    Viz.responsive(host, (width) => {
      const W = Math.max(width, 1040);
      const H = 384;
      const { svg, tex, done } = svgStage(host, W, H, "OPI: search proposes, scores and selects actions from every actor; update trains the learner from the replay buffer; the learner rejoins the candidates");
      const y0 = 112;
      const bh = 96;
      const mid = y0 + bh / 2;
      const X = { S: [0, 0.07], P: [0.09, 0.165], Sc: [0.274, 0.18], Sel: [0.474, 0.102], E: [0.598, 0.112], D: [0.734, 0.118], L: [0.874, 0.122] };
      const px = (k) => X[k][0] * W;
      const pw = (k) => X[k][1] * W;
      const cx = (k) => px(k) + pw(k) / 2;
      const frame = (k, stroke = C.lineStrong, sw = 1.3, fill = "#fff") =>
        Viz.el("rect", { x: px(k), y: y0, width: pw(k), height: bh, rx: 12, fill, stroke, "stroke-width": sw }, svg);
      const title = (k, html) => tex(cx(k), y0 + 34, html, { cls: "pl-title" });
      const sub = (k, html) => tex(cx(k), y0 + 66, html, { cls: "pl-math" });

      frame("S"); title("S", "State"); sub("S", String.raw`\(s_t\)`);
      frame("P", C.bp, 2.2); title("P", String.raw`Candidates \(\mathcal C_t\)`);
      const POOL = [C.learner, C.oracle1, C.oracle2, C.oracle3];
      for (let i = 0; i < 8; i++) {
        const gx = cx("P") - 76 + i * 19 + Math.floor(i / 2) * 6;
        Viz.el("circle", { cx: gx, cy: y0 + 66, r: 7, fill: POOL[Math.floor(i / 2)] }, svg);
      }
      frame("Sc", C.bp, 2.2); title("Sc", "Source-aware scores"); sub("Sc", String.raw`\(\widehat S^{(k)}(s_t,a)\)`);
      frame("Sel", C.bp, 2.2); title("Sel", "Select"); sub("Sel", String.raw`\(\hat a_t\sim p_t\)`);
      frame("E"); tex(cx("E"), mid, "Environment", { cls: "pl-title" });
      frame("D", C.pi, 2.2); title("D", "Replay buffer"); sub("D", String.raw`\(\mathcal D\)`);
      frame("L", C.pi, 2.2); title("L", "Learner"); sub("L", String.raw`\(\pi_\theta\)`);

      const gap = 3;
      arrow(svg, [[px("S") + pw("S"), mid], [px("P") - gap, mid]]);
      arrow(svg, [[px("P") + pw("P"), mid], [px("Sc") - gap, mid]]);
      arrow(svg, [[px("Sc") + pw("Sc"), mid], [px("Sel") - gap, mid]]);
      arrow(svg, [[px("Sel") + pw("Sel"), mid], [px("E") - gap, mid]]);
      tex((px("Sel") + pw("Sel") + px("E")) / 2, mid - 16, String.raw`\(\hat a_t\)`, { cls: "pl-math" });
      arrow(svg, [[px("E") + pw("E"), mid], [px("D") - gap, mid]]);
      arrow(svg, [[px("D") + pw("D"), mid], [px("L") - gap, mid]]);

      // critics: trained from the buffer, used by both search and update
      const cy0 = y0 + bh + 54;
      const ch = 68;
      const crx = 0.70 * W;
      const crw = 0.19 * W;
      Viz.el("rect", { x: crx, y: cy0, width: crw, height: ch, rx: 12, fill: C.wash, stroke: C.lineStrong, "stroke-width": 1.3 }, svg);
      tex(crx + crw / 2, cy0 + 24, "Critic ensembles", { cls: "pl-title small" });
      tex(crx + crw / 2, cy0 + 50, String.raw`\(\{Q_k,\sigma_k\}_{k=0}^{K}\)`, { cls: "pl-math" });
      arrow(svg, [[cx("D"), y0 + bh], [cx("D"), cy0 - gap]]);
      const cmid = cy0 + ch / 2;
      arrow(svg, [[crx, cmid], [cx("Sc"), cmid], [cx("Sc"), y0 + bh + gap]], C.bp, { dash: "6 4", width: 2 });
      tex((crx + cx("Sc")) / 2, cmid - 15, String.raw`\(Q_k,\ \sigma_k\)`, { cls: "pl-math", color: C.bp });
      const lIn = px("L") + pw("L") * 0.3;
      arrow(svg, [[crx + crw, cmid], [lIn, cmid], [lIn, y0 + bh + gap]], C.pi, { dash: "6 4", width: 2 });
      tex(lIn - 8, (y0 + bh + cmid) / 2, String.raw`\(Q_0\)`, { cls: "pl-math", align: "right", color: C.pi });

      // the updated learner rejoins the candidates
      const lOut = px("L") + pw("L") * 0.78;
      const yb = H - 18;
      arrow(svg, [[lOut, y0 + bh], [lOut, yb], [cx("P"), yb], [cx("P"), y0 + bh + gap]], C.learner, { width: 2.4 });
      tex((cx("P") + crx) / 2, yb - 15, String.raw`updated learner rejoins as \(\pi_0\)`, { cls: "pl-note", color: C.learner });

      // component brackets + pills
      const pill = (x0, x1, color, html, pillW) => {
        Viz.el("path", { d: `M${x0},${y0 - 12} V${y0 - 26} H${x1} V${y0 - 12}`, fill: "none", stroke: color, "stroke-width": 2 }, svg);
        const pcx = Math.min(Math.max((x0 + x1) / 2, pillW / 2 + 2), W - pillW / 2 - 2);
        Viz.el("rect", { x: pcx - pillW / 2, y: y0 - 80, width: pillW, height: 40, rx: 20, fill: color }, svg);
        tex(pcx, y0 - 60, html, { cls: "pl-pill", color: "#fff" });
      };
      pill(px("P"), px("Sel") + pw("Sel"), C.bp, String.raw`<b>Search</b>&nbsp;·&nbsp;behavior policy`, 300);
      pill(px("D"), px("L") + pw("L"), C.pi, String.raw`<b>Update</b>&nbsp;·&nbsp;GABC + DPG`, 230);
      done();
    });
  }

  // ======================================================================
  // Setting: a route of 9 states, three oracles, one learner
  // ======================================================================
  const ROUTE = {
    segs: [["highway", 0, 3], ["city streets", 3, 6], ["rural roads", 6, 9]],
    oracles: [
      { name: "highway expert", color: C.oracle1, V: [0.9, 0.92, 0.86, 0.32, 0.25, 0.22, 0.34, 0.3, 0.28] },
      { name: "city expert", color: C.oracle2, V: [0.3, 0.34, 0.42, 0.9, 0.93, 0.86, 0.3, 0.26, 0.24] },
      { name: "rural expert", color: C.oracle3, V: [0.24, 0.22, 0.2, 0.3, 0.34, 0.32, 0.86, 0.92, 0.9] },
    ],
  };
  const N_S = 9;

  // shared column geometry for the two route figures
  function routeAxis(svg, tex, W, lab, top) {
    const cw = (W - lab - 8) / N_S;
    const cx = (i) => lab + i * cw + cw / 2;
    ROUTE.segs.forEach(([name, a, b], si) => {
      const x0 = lab + a * cw + 2, x1 = lab + b * cw - 2;
      Viz.el("rect", { x: x0, y: top, width: x1 - x0, height: 26, rx: 6, fill: "#e7e5df" }, svg);
      tex((x0 + x1) / 2, top + 13, name, { cls: "ml-head" });
    });
    for (let i = 0; i < N_S; i++) tex(cx(i), top + 44, String.raw`\(s_{${i + 1}}\)`, { cls: "pl-math" });
    arrow(svg, [[lab, top + 62], [W - 8, top + 62]], C.faint, { width: 1.6 });
    tex(W - 10, top + 76, "time", { cls: "ml-dim", align: "right" });
    return { cw, cx };
  }

  function renderSetting(host = byId("setting-chart")) {
    Viz.responsive(host, (width) => {
      const W = Math.max(width, 760);
      const lab = 262;
      const rh = 44;
      const top = 4;
      const rows0 = top + 96;
      const H = rows0 + 4 * rh + 40;
      const { svg, tex, done } = svgStage(host, W, H, "Three oracles are each good on one part of a route; the learner starts weak");
      const { cw, cx } = routeAxis(svg, tex, W, lab, top);
      const rowsData = [...ROUTE.oracles.map((o, k) => ({ ...o, k: k + 1 })), { name: "learner", color: C.learner, V: Array(N_S).fill(0.16), k: "\\theta" }];
      rowsData.forEach((o, r) => {
        const y = rows0 + r * rh;
        Viz.el("circle", { cx: 12, cy: y + rh / 2, r: 7, fill: o.color }, svg);
        tex(28, y + rh / 2 - (r === 3 ? 8 : 0), String.raw`\(\pi_{${o.k}}\)&nbsp; ${o.name}`, { cls: "ml-head", align: "left" });
        if (r === 3) tex(28, y + rh / 2 + 11, "starts weak, learns from all oracles", { cls: "ml-dim", align: "left" });
        o.V.forEach((v, i) => {
          Viz.el("rect", { x: lab + i * cw + 3, y: y + 4, width: cw - 6, height: rh - 8, rx: 6, fill: Viz.mix("#f4f3ef", o.color, v * 0.95) }, svg);
        });
      });
      tex(lab, H - 14, String.raw`cell shade: value \(V^{\pi}(s_t)\), how well the policy does from \(s_t\) on`, { cls: "ml-dim", align: "left" });
      done();
    });
  }

  // ======================================================================
  // Preliminaries: who acts at each state, for three compositions
  // ======================================================================
  function renderPrelim(host = byId("prelim-chart")) {
    // acting oracle per state (0-based oracle index); "pick" marks action-level choices
    const ROWS = [
      { name: "Best oracle", eq: String.raw`\(\pi^*=\arg\max_{k} J(\pi_k)\)`, act: Array(N_S).fill(1), ret: 0.46, note: "one oracle for the whole episode" },
      { name: "Max-following", eq: String.raw`\(\pi^{\bullet}(s)=\pi_{k^*(s)}(s),\ k^*(s)=\arg\max_k V^{\pi_k}(s)\)`, act: [0, 0, 0, 1, 1, 1, 2, 2, 2], ret: 0.8, note: "the best oracle at each state" },
      { name: "Max-aggregation", eq: String.raw`\(\pi^{\max}(s)=\arg\max_{a}A_{\max}(s,a)\)`, act: [0, 0, 1, 1, 1, 2, 2, 2, 2], ret: 0.88, note: "the best action at each state", pick: [2, 5], ours: true },
    ];
    Viz.responsive(host, (width) => {
      const W = Math.max(width, 820);
      const lab = 350;
      const retW = 120;
      const Wg = W - retW;
      const rh = 62;
      const top = 4;
      const rows0 = top + 96;
      const H = rows0 + ROWS.length * rh + 34;
      const { svg, tex, done } = svgStage(host, W, H, "Which oracle acts at each state under best-oracle, max-following and max-aggregation, and the return each gets");
      const { cw, cx } = routeAxis(svg, tex, Wg, lab, top);
      tex(Wg + retW / 2 + 4, top + 44, "return", { cls: "ml-head" });
      ROWS.forEach((row, r) => {
        const y = rows0 + r * rh;
        tex(0, y + 20, row.name, { cls: "pl-title small", align: "left", color: row.ours ? C.ours : C.ink });
        tex(0, y + 44, row.eq, { cls: "ml-small", align: "left" });
        row.act.forEach((k, i) => {
          const o = ROUTE.oracles[k];
          Viz.el("rect", { x: lab + i * cw + 3, y: y + 6, width: cw - 6, height: rh - 16, rx: 6, fill: o.color, opacity: 0.88 }, svg);
          if (row.pick && row.pick.includes(i)) Viz.el("rect", { x: lab + i * cw + 3, y: y + 6, width: cw - 6, height: rh - 16, rx: 6, fill: "none", stroke: C.ink, "stroke-width": 2.6 }, svg);
        });
        // return bar (illustrative)
        const bx = Wg + 14, bw = retW - 30;
        Viz.el("rect", { x: bx, y: y + 16, width: bw, height: 18, rx: 4, fill: C.wash }, svg);
        Viz.el("rect", { x: bx, y: y + 16, width: bw * row.ret, height: 18, rx: 4, fill: row.ours ? C.ours : C.ink2 }, svg);
      });
      const leg = ROUTE.oracles.map((o) => `<span style="display:inline-flex;align-items:center;gap:5px;margin-right:14px"><i style="width:12px;height:12px;border-radius:3px;background:${o.color};display:inline-block"></i>${o.name}</span>`).join("");
      tex(lab, H - 14, `cell: whose action is executed &nbsp; ${leg}<span style="display:inline-flex;align-items:center;gap:5px"><i style="width:12px;height:12px;border:2.4px solid ${C.ink};border-radius:3px;display:inline-block"></i>another oracle's action</span>`, { cls: "ml-dim", align: "left" });
      done();
    });
  }

  // ======================================================================
  // Foundation: one-step lookahead behind A_max and the proxy
  // ======================================================================
  function renderProxy(host = byId("proxy-chart"), opts = {}) {
    const showProxy = opts.showProxy !== false;
    const Q = [0.45, 0.66, 0.6, 0.38]; // take a, then follow actor k
    const BEST = 0.76; // take a, then the best actor at s'
    const VMAX = 0.5;
    const COLORS = [C.learner, C.oracle1, C.oracle2, C.oracle3];
    Viz.responsive(host, (width) => {
      const W = Math.max(width, 460);
      const H = 380;
      const { svg, tex, done } = svgStage(host, W, H, "Bars: value of taking a then following one fixed actor; outline: taking a then the best actor at the next state; dashed: V max at s");
      const left = 78, right = W - 70, top = 40, bottom = H - 78;
      const y = Viz.linear([0, 0.8], [bottom, top]);
      [0, 0.2, 0.4, 0.6, 0.8].forEach((t) => Viz.el("line", { x1: left, x2: right, y1: y(t), y2: y(t), stroke: C.grid }, svg));
      tex(left, 14, String.raw`take \(a\) at \(s\), then …`, { cls: "ml-head", align: "left" });
      const n = 5;
      const slot = (right - left) / (n + 0.4);
      const bx = (i) => left + (i + (i === 4 ? 0.4 : 0)) * slot + slot * 0.18;
      const bw = slot * 0.64;
      Q.forEach((q, k) => {
        Viz.el("rect", { x: bx(k), y: y(q), width: bw, height: bottom - y(q), rx: 3, fill: COLORS[k], opacity: q === Math.max(...Q) ? 0.95 : 0.55 }, svg);
        tex(bx(k) + bw / 2, bottom + 18, String.raw`follow \(\pi_${k}\)`, { cls: "ml-small" });
        tex(bx(k) + bw / 2, bottom + 40, String.raw`\(Q^{\pi_${k}}\)`, { cls: "ml-small", color: C.muted });
      });
      Viz.el("rect", { x: bx(4), y: y(BEST), width: bw, height: bottom - y(BEST), rx: 3, fill: "none", stroke: C.ink, "stroke-width": 2.2, "stroke-dasharray": "5 3" }, svg);
      tex(bx(4) + bw / 2, bottom + 18, "best actor", { cls: "ml-small" });
      tex(bx(4) + bw / 2, bottom + 40, String.raw`at each \(s'\)`, { cls: "ml-small", color: C.muted });
      Viz.el("line", { x1: left, x2: right - 12, y1: y(VMAX), y2: y(VMAX), stroke: C.ink, "stroke-width": 1.6, "stroke-dasharray": "6 4" }, svg);
      tex(left - 6, y(VMAX), String.raw`\(V_{\max}(s)\)`, { cls: "pl-math", align: "right" });
      // brackets on the right edge
      const br = (x, y1, y2, color, html, dy) => {
        Viz.el("path", { d: `M${x - 6},${y1} H${x} V${y2} H${x - 6}`, fill: "none", stroke: color, "stroke-width": 2.4 }, svg);
        tex(x + 8, (y1 + y2) / 2 + dy, html, { cls: "pl-math", align: "left", color });
      };
      br(bx(4) + bw + 10, y(BEST), y(VMAX), C.ink, String.raw`\(A_{\max}\)`, -6);
      if (showProxy) Viz.el("line", { x1: bx(1) + bw, x2: bx(4) - 14, y1: y(Math.max(...Q)), y2: y(Math.max(...Q)), stroke: C.ours, "stroke-width": 1.4, "stroke-dasharray": "3 3" }, svg);
      const px0 = bx(4) - 14;
      if (showProxy) Viz.el("path", { d: `M${px0 - 6},${y(Math.max(...Q))} H${px0} V${y(VMAX)} H${px0 - 6}`, fill: "none", stroke: C.ours, "stroke-width": 2.4 }, svg);
      if (showProxy) tex(px0 - 10, (y(Math.max(...Q)) + y(VMAX)) / 2, String.raw`\(\tilde A_{\mathrm{proxy}}\)`, { cls: "pl-math", align: "right", color: C.ours });
      done();
    });
  }

  // ======================================================================
  // Search: source-aware scoring at a city street
  // ======================================================================
  const BP = {
    names: ["learner", "highway", "city"],
    colors: [C.learner, C.oracle1, C.oracle2],
    // rows: critic k; columns: candidate proposed by actor j
    Q: [
      [0.52, 0.85, 0.47],
      [0.4, 0.5, 0.45],
      [0.3, 0.32, 0.64],
    ],
    sigma: [
      [0.02, 0.2, 0.06],
      [0.05, 0.02, 0.06],
      [0.05, 0.05, 0.02],
    ],
    alpha: 3,
    tau: 0.1,
  };
  const BP_CAPTION = {
    aware: "With the penalty, the city expert's own action wins on a city street.",
    raw: "Without the penalty, the learner's critic over-values the highway action.",
  };

  function bpScores(mode) {
    const S = BP.Q.map((row, k) => row.map((q, j) => (j === k || mode === "raw" ? q : q - BP.alpha * BP.sigma[k][j])));
    const best = [0, 1, 2].map((j) => [0, 1, 2].reduce((kk, k) => (S[k][j] > S[kk][j] ? k : kk), 0));
    const e = best.map((k, j) => Math.exp(S[k][j] / BP.tau)); // V_max cancels in the softmax
    const Z = e.reduce((s, v) => s + v, 0);
    return { S, best, p: e.map((v) => v / Z) };
  }

  function renderBP(host = byId("bp-grid"), opts = {}) {
    const fixed = Boolean(opts.mode);
    let mode = opts.mode || "aware";
    let cap = fixed ? null : byId("bp-caption");
    let redraw = () => {};
    if (!fixed) segmented(byId("bp-mode"), (b) => { mode = b.dataset.mode; redraw(); });
    Viz.responsive(host, (width) => {
      redraw = () => {
        host.replaceChildren();
        if (fixed) { cap = node("p", "toy-caption"); }
        cap.textContent = BP_CAPTION[mode];
        const { S, best, p } = bpScores(mode);
        const W = width;
        const lab = 138;
        const cw = (W - lab - 4) / 3;
        const rh = 64;
        const top = 74;
        const gridB = top + 3 * rh;
        const barTop = gridB + 22;
        const barH = 104;
        const H = barTop + barH + 12;
        const { svg, tex, done } = svgStage(host, W, H, "Rows are critics, columns are candidate actions; the best score per column sets the pick probability");
        const pat = Viz.el("pattern", { id: "bp-hatch", width: 7, height: 7, patternUnits: "userSpaceOnUse", patternTransform: "rotate(45)" }, Viz.el("defs", {}, svg));
        Viz.el("rect", { width: 7, height: 7, fill: "#f6f5f0" }, pat);
        Viz.el("line", { x1: 0, y1: 0, x2: 0, y2: 7, stroke: "#e2e1d8", "stroke-width": 3 }, pat);
        tex(lab - 14, 46, "action from", { cls: "ml-dim", align: "right" });
        [0, 1, 2].forEach((j) => {
          const x = lab + j * cw + cw / 2;
          Viz.el("circle", { cx: x, cy: 18, r: 10, fill: BP.colors[j] }, svg);
          tex(x, 46, BP.names[j], { cls: "ml-head" });
        });
        [0, 1, 2].forEach((k) => {
          const y = top + k * rh;
          tex(lab - 14, y + rh / 2, String.raw`critic of ${BP.names[k]}`, { cls: "ml-head", align: "right" });
          [0, 1, 2].forEach((j) => {
            const x = lab + j * cw;
            const own = j === k;
            const isBest = best[j] === k;
            const trap = mode === "raw" && k === 0 && j === 1;
            Viz.el("rect", { x: x + 4, y: y + 4, width: cw - 8, height: rh - 8, rx: 7, fill: own || mode === "raw" ? "#fff" : "url(#bp-hatch)", stroke: trap ? C.bad : isBest ? C.ink : C.lineStrong, "stroke-width": isBest || trap ? 2.6 : 1 }, svg);
            Viz.text(svg, S[k][j].toFixed(2), { x: x + cw / 2, y: y + rh / 2 + (trap ? 1 : 6), "text-anchor": "middle", "font-size": 17, "font-weight": isBest ? 800 : 560, fill: own || mode === "raw" ? C.ink : C.muted });
            if (trap) Viz.text(svg, "over-valued", { x: x + cw / 2, y: y + rh - 11, "text-anchor": "middle", "font-size": 13, "font-weight": 700, fill: C.bad });
          });
        });
        tex(lab - 14, barTop + barH - 10, "select", { cls: "ml-head", align: "right" });
        Viz.el("line", { x1: lab, x2: W - 4, y1: barTop + barH, y2: barTop + barH, stroke: C.lineStrong }, svg);
        const jmax = p.indexOf(Math.max(...p));
        p.forEach((v, j) => {
          const x = lab + j * cw + cw * 0.3;
          const h = v * barH;
          Viz.el("rect", { x, y: barTop + barH - h, width: cw * 0.4, height: h, rx: 3, fill: BP.colors[j], stroke: j === jmax ? C.ink : "none", "stroke-width": 2 }, svg);
          Viz.text(svg, `${Math.round(v * 100)}%`, { x: x + cw * 0.2, y: barTop + barH - h - 7, "text-anchor": "middle", "font-size": 14, "font-weight": j === jmax ? 800 : 600, fill: C.ink });
        });
        if (fixed) host.appendChild(cap);
        done();
      };
      redraw();
    });
  }

  // ======================================================================
  // Update: plain BC vs GABC vs GABC + DPG on one action dimension
  // ======================================================================
  // replayed actions at one state: [action, actor (0 learner, 1 highway, 2 city, 3 rural), Ã_proxy]
  const BUF = [[-0.85, 1, -0.14], [-0.7, 3, -0.12], [-0.55, 0, -0.1], [-0.3, 3, -0.05], [-0.1, 1, 0], [0.16, 2, 0.04], [0.24, 2, 0.06], [0.3, 0, 0.05], [0.38, 2, 0.03]];
  const ETA = 0.03; // schematic temperature, sharper than the paper's 0.1 so the weighting is visible
  const QF = (a) => 1 - 0.45 * (a - 0.7) ** 2;
  const PI_CAPTION = {
    bc: "Plain BC copies every replayed action equally, good or bad.",
    gabc: "GABC up-weights actions with high proxy advantage, so the learner copies the good ones.",
    both: "With DPG, the learner's action moves past every replayed action, to a higher critic value.",
  };

  function renderPI(host = byId("pi-chart"), opts = {}) {
    const fixed = Boolean(opts.mode);
    let mode = opts.mode || "both";
    let cap = fixed ? null : byId("pi-caption");
    let redraw = () => {};
    if (!fixed) segmented(byId("pi-mode"), (b) => { mode = b.dataset.mode; redraw(); });
    const COLORS = [C.learner, C.oracle1, C.oracle2, C.oracle3];
    Viz.responsive(host, (width) => {
      redraw = () => {
        host.replaceChildren();
        if (fixed) { cap = node("p", "toy-caption"); }
        cap.textContent = PI_CAPTION[mode];
        const W = width;
        const H = 452;
        const { svg, tex, done } = svgStage(host, W, H, "The learner's critic over one action dimension, replayed actions with their imitation weights, and the learner's action under plain BC, GABC and GABC plus DPG");
        const L = 22, Rr = W - 22;
        const X = (a) => L + ((a + 1) / 2) * (Rr - L);
        const qT = 84, qB = 196;
        const Yq = Viz.linear([-0.35, 1.05], [qB, qT]);
        const wB = 322, wT = 252;
        const axisY = 352;
        tex(L, 14, String.raw`learner's critic \(Q^{\pi_\theta}(s,a)\): higher is better`, { cls: "ml-head bg", align: "left" });
        const pts = Array.from({ length: 81 }, (_, i) => -1 + i / 40).map((a) => `${X(a)},${Yq(QF(a))}`).join(" ");
        Viz.el("polyline", { points: pts, fill: "none", stroke: C.ink2, "stroke-width": 2.4 }, svg);
        const weighted = mode !== "bc";
        tex(L, wT - 20, weighted ? String.raw`imitation weight \(w(s,a)\)` : "equal imitation weights", { cls: "ml-head bg", align: "left" });
        Viz.el("line", { x1: L, x2: Rr, y1: wB, y2: wB, stroke: C.lineStrong }, svg);
        let sw = 0, sa = 0, mean = 0;
        const wmax = Math.max(...BUF.map(([, , ad]) => Math.exp(ad / ETA)));
        BUF.forEach(([a, k, ad]) => {
          const w = weighted ? Math.exp(ad / ETA) : 1;
          sw += w; sa += w * a; mean += a / BUF.length;
          const h = weighted ? (w / wmax) * (wB - wT - 6) : (wB - wT) * 0.42;
          Viz.el("line", { x1: X(a), x2: X(a), y1: wB, y2: wB - h, stroke: COLORS[k], "stroke-width": 3 }, svg);
          Viz.el("circle", { cx: X(a), cy: wB - h, r: 7, fill: COLORS[k] }, svg);
        });
        Viz.el("line", { x1: L, x2: Rr, y1: axisY, y2: axisY, stroke: C.ink2, "stroke-width": 1.4 }, svg);
        tex(Rr, axisY + 36, String.raw`action \(a\)`, { cls: "ml-dim", align: "right" });
        const aBC = mean;
        const aG = sa / sw;
        const aD = 0.56;
        const star = (x, yy, color, r = 12) => {
          const pts2 = [];
          for (let i = 0; i < 10; i++) {
            const rr = i % 2 ? r * 0.46 : r;
            const t = -Math.PI / 2 + (i * Math.PI) / 5;
            pts2.push(`${x + rr * Math.cos(t)},${yy + rr * Math.sin(t)}`);
          }
          Viz.el("polygon", { points: pts2.join(" "), fill: color, stroke: "#fff", "stroke-width": 1.2 }, svg);
        };
        const mark = (a, color, label, faint) => {
          Viz.el("line", { x1: X(a), x2: X(a), y1: Yq(QF(a)), y2: axisY, stroke: color, "stroke-width": 1.4, "stroke-dasharray": "4 4", opacity: faint ? 0.45 : 0.85 }, svg);
          Viz.el("circle", { cx: X(a), cy: Yq(QF(a)), r: 6.5, fill: color, stroke: "#fff", "stroke-width": 1.5, opacity: faint ? 0.5 : 1 }, svg);
          star(X(a), axisY, color);
          tex(X(a), axisY + 22, label, { cls: "ml-head", color: faint ? C.faint : color });
          tex(X(a), Yq(QF(a)) - 16, QF(a).toFixed(2), { cls: "ml-small", color: faint ? C.faint : C.ink });
        };
        if (mode === "bc") mark(aBC, C.ink2, "plain BC", false);
        if (mode === "gabc") { mark(aBC, C.faint, "plain BC", true); mark(aG, C.learner, "GABC", false); }
        if (mode === "both") {
          mark(aBC, C.faint, "plain BC", true);
          mark(aG, C.learner, "GABC", false);
          const curve = Array.from({ length: 13 }, (_, i) => aG + ((aD - aG) * i) / 12).map((a) => [X(a), Yq(QF(a)) - 30]);
          arrow(svg, curve, C.pi, { width: 2.8 });
          tex((X(aG) + X(aD)) / 2, Yq(QF((aG + aD) / 2)) - 46, "DPG", { cls: "ml-tag", color: C.pi });
          mark(aD, C.pi, "+ DPG", false);
        }
        tex(L, H - 14, String.raw`star: learner's action \(\pi_\theta(s)\); number: its critic value`, { cls: "ml-dim", align: "left" });
        if (fixed) host.appendChild(cap);
        done();
      };
      redraw();
    });
  }

  // ======================================================================
  // Experiments: what NAUC and Final measure (schematic)
  // ======================================================================
  function renderMetrics(host = byId("metric-chart")) {
    Viz.responsive(host, (width) => {
      const W = width;
      const H = 230;
      const { svg, tex, done } = svgStage(host, W, H, "Two learning curves with the same final performance; the faster one has a larger area under the curve");
      const L = 40, Rr = W - 70, T = 18, B = H - 40;
      const X = (t) => L + t * (Rr - L);
      const Y = Viz.linear([0, 1], [B, T]);
      const fast = (t) => 1 - Math.exp(-7 * t);
      const slow = (t) => Math.min(1, Math.max(0, (t - 0.25) / 0.65)) ** 1.3;
      const pts = (f) => Array.from({ length: 61 }, (_, i) => i / 60).map((t) => [X(t), Y(f(t))]);
      const area = pts(fast).map((p) => p.join(",")).join(" ");
      Viz.el("polygon", { points: `${X(0)},${Y(0)} ${area} ${X(1)},${Y(0)}`, fill: "rgba(78,121,167,0.16)" }, svg);
      Viz.el("polyline", { points: pts(slow).map((p) => p.join(",")).join(" "), fill: "none", stroke: C.base, "stroke-width": 2.6 }, svg);
      Viz.el("polyline", { points: area, fill: "none", stroke: C.ours, "stroke-width": 2.8 }, svg);
      Viz.el("line", { x1: L, x2: Rr, y1: B, y2: B, stroke: C.lineStrong }, svg);
      Viz.el("line", { x1: L, x2: L, y1: T, y2: B, stroke: C.lineStrong }, svg);
      tex(L, B + 18, "0", { cls: "ml-dim" });
      tex(Rr, B + 18, String.raw`\(T\)`, { cls: "pl-math" });
      tex((L + Rr) / 2, B + 22, "environment steps", { cls: "ml-dim" });
      tex(16, (T + B) / 2, String.raw`\(\mathrm{perf}(t)\)`, { cls: "ml-dim rot" });
      Viz.el("circle", { cx: X(1), cy: Y(1), r: 6, fill: C.ink }, svg);
      tex(X(1) + 10, Y(1), "Final", { cls: "ml-head", align: "left" });
      tex(X(0.4), Y(0.66), "NAUC = shaded area / T", { cls: "ml-head", color: C.ours });
      tex(X(0.52) + 10, Y(0.2), "slower learner", { cls: "ml-small bg", color: C.muted, align: "left" });
      done();
    });
  }

  // ======================================================================
  // Experiments
  // ======================================================================
  const SHORT = {
    "Assembly-Sparse": "Assembly", "Drawer-Open-Sparse": "Drawer-Open", "Hammer-Sparse": "Hammer", "Push-Wall-Sparse": "Push-Wall",
    "Hopper-Hop": "Hopper-Hop", "Quadruped-Run": "Quadruped-Run", BipedalWalker: "BipedalWalker", WeatherDriving: "WeatherDriving",
  };
  const UNIT = { "Hopper-Hop": "return", "Quadruped-Run": "return" };

  function renderSetup(row = byId("setup-row")) {
    const tiles = [
      ["10", "MetaWorld manipulation"],
      ["5", "DeepMind Control (DMC) locomotion"],
      ["4", "Custom Box2D control"],
    ];
    row.innerHTML =
      tiles.map(([n, t]) => `<div class="setup-tile"><b>${n}</b><span>${t}</span></div>`).join("") +
      `<div class="setup-tile"><b>6</b><span>baselines; Max-V and Max-Q imitate max-following and max-aggregation (via max-Q)</span><div class="chips">${["QMP", "CUP", "LOKI", "MAPS", "Max-V", "Max-Q"].map((m) => `<span class="chip">${m}</span>`).join("")}</div></div>`;
  }

  function niceMax(v) {
    if (v <= 1.0001) return 1;
    const step = v > 500 ? 200 : 100;
    return Math.ceil(v / step) * step;
  }

  function taskPanels(hostId, tasks, metric) {
    const host = typeof hostId === "string" ? byId(hostId) : hostId;
    host.replaceChildren();
    tasks.forEach((t) => {
      const panel = node("div");
      const unit = UNIT[t.task] ? "return" : "success rate";
      panel.append(node("h5", "", SHORT[t.task]), node("p", "sm-unit", unit));
      const chart = node("div", "chart");
      panel.appendChild(chart);
      host.appendChild(panel);
      const vals = t.methods.map((m) => m[metric]);
      const dmax = niceMax(Math.max(...vals));
      const digits = dmax > 1 ? 0 : 2;
      Viz.responsive(chart, (width) => {
        const rowH = 23;
        const lw = 56;
        const vw = 44;
        const H = t.methods.length * rowH + 8;
        const svg = Viz.svgRoot(chart, width, H, `${t.task} ${metric}`);
        const x = Viz.linear([0, dmax], [lw, width - vw]);
        t.methods.forEach((m, i) => {
          const y = 4 + i * rowH;
          const ours = m.name === "OPI";
          Viz.text(svg, m.name, { x: lw - 8, y: y + 15, "text-anchor": "end", "font-size": 12, "font-weight": ours ? 800 : 500, fill: ours ? C.ink : C.muted });
          Viz.el("rect", { x: lw, y: y + 4, width: x(dmax) - lw, height: 14, rx: 3, fill: C.wash }, svg);
          const bar = Viz.el("rect", { x: lw, y: y + 4, width: Math.max(1.5, x(m[metric]) - lw), height: 14, rx: 3, fill: ours ? C.ours : C.base }, svg);
          Viz.text(svg, metric === "final" && dmax <= 1 ? `${Math.round(m[metric] * 100)}%` : m[metric].toFixed(digits), { x: width - vw + 6, y: y + 15, "font-size": 12, "font-weight": ours ? 800 : 500, fill: C.ink, "font-variant-numeric": "tabular-nums" });
          const std = m[`${metric}_std`];
          Viz.bindTip(bar, { title: `${m.name} · ${SHORT[t.task]}`, rows: [{ label: metric === "nauc" ? "NAUC" : "Final", value: `${m[metric].toFixed(3)} ± ${std.toFixed(3)}` }] });
        });
      });
    });
  }

  function renderComposition(host) {
    const legend = node("div", "legend");
    host.before && host.parentNode && !host.previousElementSibling?.classList.contains("legend") && host.parentNode.insertBefore(legend, host);
    Viz.renderLegend(legend, [
      { label: "Best single oracle", color: C.base },
      { label: "OPI", color: C.ours },
    ]);
    Viz.dumbbell(host, {
      rows: R.composition.map((c) => ({ label: SHORT[c.task], a: c.best_oracle * 100, b: c.opi_final * 100 })),
      aName: "Best single oracle", bName: "OPI", aColor: C.base, bColor: C.ours,
      domain: [0, 100], unit: "%", digits: 0, labelWidth: 130, rowHeight: 30,
      label: "Final success rate: best single oracle vs OPI",
    });
  }

  function renderResults() {
    const titles = { nauc: "NAUC: normalized area under the learning curve", final: "Final performance (success rate or return)" };
    const state = { sparse: "nauc", dense: "nauc" };
    const draw = (which) => {
      byId(`${which}-title`).textContent = titles[state[which]];
      taskPanels(`chart-${which}`, R[which], state[which]);
    };
    document.querySelectorAll(".metric-toggle").forEach((seg) =>
      segmented(seg, (b) => { state[seg.dataset.target] = b.dataset.metric; draw(seg.dataset.target); })
    );
    draw("sparse");
    draw("dense");
    ["sparse", "dense"].forEach((which) =>
      Viz.renderTable(byId(`card-${which}`), {
        columns: ["Task", "Method", "NAUC", "Final"],
        rows: R[which].flatMap((t) => t.methods.map((m) => [SHORT[t.task], m.name, `${m.nauc.toFixed(3)} ± ${m.nauc_std.toFixed(3)}`, `${m.final.toFixed(3)} ± ${m.final_std.toFixed(3)}`])),
      })
    );

    // Q3: composition
    Viz.renderLegend(byId("comp-legend"), [
      { label: "Best single oracle", color: C.base },
      { label: "OPI", color: C.ours },
    ]);
    renderComposition(byId("chart-comp"));
    Viz.renderTable(byId("card-comp"), {
      columns: ["Task", "Best single oracle", "OPI final"],
      rows: R.composition.map((c) => [SHORT[c.task], `${Math.round(c.best_oracle * 100)}%`, `${Math.round(c.opi_final * 100)}%`]),
    });
    if (false) Viz.dumbbell(byId("chart-comp"), {
      rows: R.composition.map((c) => ({ label: SHORT[c.task], a: c.best_oracle * 100, b: c.opi_final * 100 })),
      aName: "Best single oracle", bName: "OPI", aColor: C.base, bColor: C.ours,
      domain: [0, 100], unit: "%", digits: 0, labelWidth: 130, rowHeight: 30,
      label: "Final success rate: best single oracle vs OPI",
    });

    // Q4: actor selection (paper figures)
    Viz.renderLegend(byId("sel-legend"), [
      { label: "Learner", color: C.learner, shape: "rect" },
      { label: "Oracle 1", color: C.oracle1, shape: "rect" },
      { label: "Oracle 2", color: C.oracle2, shape: "rect" },
    ]);
    byId("sel-figs").innerHTML = [["assembly", "Assembly-Sparse"], ["drawer", "Drawer-Open-Sparse"]].map(([f, name]) =>
      `<figure><figcaption>${name}</figcaption><img src="media/figures/sel_${f}_OPI.svg" width="656" height="440" alt="OPI actor-selection ratio over training on ${name}"></figure>`).join("");
  }

  // ======================================================================
  // Ablations
  // ======================================================================
  const VARIANTS = [
    ["w/o Source-Aware", "w/o source-aware scoring"],
    ["w/o DPG", "w/o DPG"],
    ["w/o Sampling", "w/o sampling (argmax)"],
  ];

  function renderAblations() {
    const n = R.ablation.length;
    byId("abl-kpis").innerHTML = VARIANTS.map(([k, label]) =>
      `<div class="kpi"><span class="kpi-label">${label}</span><span class="kpi-value">${R.ablation_lower_nauc[k]} / ${n}</span><span class="kpi-detail">tasks with lower NAUC</span></div>`).join("");

    const dropColor = (v) => (v >= 100 ? Viz.mix("#f3f2ee", "#7fa3cb", Math.min(1, (v - 100) / 40)) : Viz.mix("#f3f2ee", "#b8322f", Math.min(1, (100 - v) / 90)));
    Viz.renderLegend(byId("abl-legend"), [
      { label: "lower than OPI", gradient: "linear-gradient(90deg,#b8322f,#f3f2ee)" },
      { label: "higher than OPI", color: "#a9c1dc", shape: "rect" },
    ]);
    renderAblHeatmap(byId("chart-abl"));
  }

  function renderAblHeatmap(host) {
    const n = R.ablation.length;
    const dropColor = (v) => (v >= 100 ? Viz.mix("#f3f2ee", "#7fa3cb", Math.min(1, (v - 100) / 40)) : Viz.mix("#f3f2ee", "#b8322f", Math.min(1, (100 - v) / 90)));
    Viz.responsive(host, (width) => {
      const lw = 190;
      const top = 54;
      const rh = 46;
      const H = top + VARIANTS.length * rh + 6;
      const Wd = Math.max(width, 820);
      const svg = Viz.svgRoot(host, Wd, H, "NAUC of each ablation relative to full OPI, per task");
      const cw = (Wd - lw) / n;
      Viz.text(svg, "Sparse rewards (MetaWorld)", { x: lw + 2 * cw, y: 14, "text-anchor": "middle", "font-size": 12, "font-weight": 750, fill: C.muted });
      Viz.text(svg, "Dense rewards (DMC, Box2D)", { x: lw + 6 * cw, y: 14, "text-anchor": "middle", "font-size": 12, "font-weight": 750, fill: C.muted });
      Viz.el("line", { x1: lw + 4 * cw, x2: lw + 4 * cw, y1: 4, y2: H, stroke: C.lineStrong, "stroke-dasharray": "3 3" }, svg);
      R.ablation.forEach((t, j) => {
        Viz.text(svg, SHORT[t.task], { x: lw + j * cw + cw / 2, y: 40, "text-anchor": "middle", "font-size": 12.5, "font-weight": 650, fill: C.ink2 });
      });
      VARIANTS.forEach(([k, label], i) => {
        const y = top + i * rh;
        Viz.text(svg, label, { x: lw - 12, y: y + rh / 2 + 5, "text-anchor": "end", "font-size": 13.5, "font-weight": 650, fill: C.ink });
        R.ablation.forEach((t, j) => {
          const opi = t.methods[0].nauc;
          const m = t.methods.find((x) => x.name === k);
          const v = (m.nauc / opi) * 100;
          const fill = dropColor(v);
          const cell = Viz.el("rect", { x: lw + j * cw + 3, y: y + 3, width: cw - 6, height: rh - 6, rx: 6, fill }, svg);
          Viz.text(svg, `${Math.round(v)}%`, { x: lw + j * cw + cw / 2, y: y + rh / 2 + 5, "text-anchor": "middle", "font-size": 14, "font-weight": 700, fill: Viz.inkFor(fill), "pointer-events": "none" });
          Viz.bindTip(cell, { title: `${label} · ${SHORT[t.task]}`, rows: [{ label: "NAUC", value: `${m.nauc.toFixed(3)} (OPI ${opi.toFixed(3)})` }] });
        });
      });
    });
  }

  function renderAblExtras() {
    Viz.renderTable(byId("card-abl"), {
      columns: ["Task", ...R.ablation[0].methods.map((m) => m.name)],
      rows: R.ablation.map((t) => [SHORT[t.task], ...t.methods.map((m) => `${m.nauc.toFixed(3)} ± ${m.nauc_std.toFixed(3)}`)]),
    });

    const leg = byId("abl2-legend");
    leg.innerHTML = [
      [C.ours, "OPI", ""], ["#383838", "w/o GABC", ""], ["#8c8c8c", "Scheduled exploration", ""], [C.ink, "Best oracle", "dash"],
    ].map(([c, t, d]) => `<span class="legend-item" style="color:${c}"><i class="ls-line ${d}"></i><span style="color:var(--ink-2)">${t}</span></span>`).join("");
  }

  window.OPI = {
    pipeline: (host) => renderPipeline(host),
    setting: (host) => renderSetting(host),
    prelim: (host) => renderPrelim(host),
    proxy: (host, o) => renderProxy(host, o),
    search: (host, o) => renderBP(host, o),
    update: (host, o) => renderPI(host, o),
    setup: (host) => renderSetup(host),
    metrics: (host) => renderMetrics(host),
    panels: (host, o) => taskPanels(host, R[o.set], o.metric || "nauc"),
    composition: (host) => renderComposition(host),
    ablation: (host) => renderAblHeatmap(host),
    ablKpis: (host) => {
      host.innerHTML = VARIANTS.map(([k, label]) =>
        `<div class="kpi"><span class="kpi-label">${label}</span><span class="kpi-value">${R.ablation_lower_nauc[k]} / ${R.ablation.length}</span><span class="kpi-detail">tasks with lower NAUC</span></div>`).join("");
    },
  };

  // project page wiring (slides.html calls window.OPI instead)
  if (byId("pipeline")) {
    renderPipeline();
    renderSetting();
    renderPrelim();
    renderProxy();
    renderBP();
    renderPI();
    renderSetup();
    renderMetrics();
    renderResults();
    renderAblations();
    renderAblExtras();
  }
})();
